SELECT * FROM logs WHERE (Image LIKE '%\\whoami.exe' ESCAPE '\' OR OriginalFileName='whoami.exe') AND (CommandLine LIKE '% -all%' ESCAPE '\' OR CommandLine LIKE '% /all%' ESCAPE '\' OR CommandLine LIKE '% –all%' ESCAPE '\' OR CommandLine LIKE '% —all%' ESCAPE '\' OR CommandLine LIKE '% ―all%' ESCAPE '\')
